Web Frontend (PWA).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Web Frontend (PWA) container

Container_Boundary(web_frontend_pwa, "Web Frontend (PWA)") {
    Component(Telehealth_UI_Module, "Telehealth UI Module", "Next.js / React", "Provides the user interface for video consultations and patient interactions.")
    Component(AI_Symptom_Checker_Module, "AI Symptom Checker Module", "React", "Interfaces with the AI symptom checker to collect inputs and display preliminary assessments.")
    Component(Offline_Caching_Module, "Offline Caching Module", "IndexedDB & Service Workers", "Enables local caching and offline payload queuing for low-bandwidth rural connections.")
}

Rel(Telehealth_UI_Module, AI_Symptom_Checker_Module, "Passes user symptom data")
Rel(Telehealth_UI_Module, Offline_Caching_Module, "Queues payloads and caches data locally")
@enduml

Media Relaying Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(media_relaying_service, "Media Relaying Service") {
    Component(sfu_media_router, "SFU Media Router", "Go, LiveKit server node", "Handles real-time WebRTC media forwarding and adaptive bitrate scaling.")
    Component(room_session_manager, "Room & Session Manager", "Node.js / Go", "Manages virtual rooms, authentication, and region-locked policies.")
    Component(telemetry_audit_collector, "Telemetry & Audit Collector", "Go", "Captures WebRTC stats and compliance metadata.")
    Component(turn_stun_relay_gateway, "TURN/STUN Relay Gateway", "Coturn / LiveKit Egress", "Handles NAT traversal and TCP fallback.")
}

Rel(sfu_media_router, telemetry_audit_collector, "Streams session quality metrics", "Internal gRPC")

@enduml

Data Storage.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Data Storage container

Container_Boundary(data_storage, "Data Storage") {
    Component(Cloud_SQL_PostgreSQL, "Cloud SQL PostgreSQL", "PostgreSQL", "Stores transactional FHIR health records, consent states, and enforces Row-Level Security.")
    Component(Google_Cloud_Storage_WORM_Buckets, "Google Cloud Storage WORM Buckets", "GCS Region-Locked Buckets", "Stores unstructured media and AI traceability inputs with WORM policies for immutability.")
}

Rel(Cloud_SQL_PostgreSQL, Google_Cloud_Storage_WORM_Buckets, "References unstructured media and AI traceability inputs", "HTTPS / GCP API")

@enduml
